16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.Period;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    @Email
62	    private String email;
63	
64	    @Column(name = "title")
65	    private String title;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "postcode")
74	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
75	    private String postcode;
76	
77	    @Column(name = "customer_code")
78	    private String customerCode;
79	
80	    @Column(name = "household_id")
81	    private String householdId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private Boolean bulkSignupWarning;
88	
89	    @Column(name = "household_size")
90	    private Integer householdSize;
91	
92	    @Column(name = "possible_duplicate")
93	    private Boolean possibleDuplicate;
94	
95	    @Column(name = "possible_duplicate_of")
96	    private Integer possibleDuplicateOf;
97	
98	    @Column(name = "deleted", nullable = false)
99	    private boolean deleted = false;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    /** Common street-type abbreviations expanded during address normalization. */
105	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
106	        "ST", "STREET",
107	        "RD", "ROAD",
108	        "AVE", "AVENUE");
109	
110	    /** Fixed city-to-region table used to derive an owner's locality. */
111	    private static final Map<String, String> CITY_REGION = Map.of(
112	        "Sydney", "NSW",
113	        "Melbourne", "VIC",
114	        "Brisbane", "QLD");
115	
116	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
117	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
118	        "NSW", new int[] {2000, 2099},
119	        "VIC", new int[] {3000, 3099},
120	        "QLD", new int[] {4000, 4099});
121	
122	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
123	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
124	        "NSW", "Australia/Sydney",
125	        "VIC", "Australia/Melbourne",
126	        "QLD", "Australia/Brisbane");
127	
128	    /**
129	     * Return the owner's address. When a structured address is supplied (a non-blank
130	     * {@code addressLine1}) it takes precedence and the value is composed as the
131	     * normalized {@code addressLine1}, with a single space and the normalized
132	     * {@code addressLine2} appended when an {@code addressLine2} is present.
133	     * Otherwise the flat {@code address} is returned, preserving backward
134	     * compatibility for owners supplied in the flat form.
135	     */
136	    public String getAddress() {
137	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
138	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
139	                return this.addressLine1 + " " + this.addressLine2;
140	            }
141	            return this.addressLine1;
142	        }
143	        return this.address;
144	    }
145	
146	    /**
147	     * Set the owner's flat address, normalizing it to a canonical form so it is both
148	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
149	     * internal runs of whitespace are collapsed to a single space, the value is
150	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
151	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
152	     * left as-is.
153	     */
154	    public void setAddress(String address) {
155	        this.address = normalizeAddress(address);
156	    }
157	
158	    public String getAddressLine1() {
159	        return this.addressLine1;
160	    }
161	
162	    /**
163	     * Set the first line of the owner's structured address, normalized the same way
164	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
165	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
166	     * as-is.
167	     */
168	    public void setAddressLine1(String addressLine1) {
169	        this.addressLine1 = normalizeAddress(addressLine1);
170	    }
171	
172	    public String getAddressLine2() {
173	        return this.addressLine2;
174	    }
175	
176	    /**
177	     * Set the optional second line of the owner's structured address, normalized the
178	     * same way as {@link #setAddressLine1(String)}. A {@code null} value is left
179	     * as-is.
180	     */
181	    public void setAddressLine2(String addressLine2) {
182	        this.addressLine2 = normalizeAddress(addressLine2);
183	    }
184	
185	    /**
186	     * Normalize an address string to its canonical form: trimmed, whitespace
187	     * collapsed, upper-cased, with common street-type abbreviations expanded.
188	     * Returns {@code null} for a {@code null} input; a value that is blank once
189	     * trimmed normalizes to the empty string.
190	     */
191	    public static String normalizeAddress(String address) {
192	        if (address == null) {
193	            return null;
194	        }
195	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
196	        if (collapsed.isEmpty()) {
197	            return "";
198	        }
199	        String[] tokens = collapsed.split(" ");
200	        StringBuilder sb = new StringBuilder();
201	        for (int i = 0; i < tokens.length; i++) {
202	            if (i > 0) {
203	                sb.append(' ');
204	            }
205	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
206	        }
207	        return sb.toString();
208	    }
209	
210	    public String getCity() {
211	        return this.city;
212	    }
213	
214	    public void setCity(String city) {
215	        this.city = city;
216	    }
217	
218	    public String getTelephone() {
219	        return this.telephone;
220	    }
221	
222	    public void setTelephone(String telephone) {
223	        this.telephone = telephone;
224	    }
225	
226	    /**
227	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
228	     * country code, a space, then the national digits grouped in threes and separated
229	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
230	     * North American country code ({@code '+1'}) is one digit; other country codes are
231	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
232	     * raw value unchanged when it is not a well-formed E.164 number.
233	     */
234	    public String getTelephoneDisplay() {
235	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
236	            return this.telephone;
237	        }
238	        String digits = this.telephone.substring(1);
239	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
240	        if (digits.length() <= countryCodeLength) {
241	            return this.telephone;
242	        }
243	        String countryCode = digits.substring(0, countryCodeLength);
244	        String national = digits.substring(countryCodeLength);
245	        StringBuilder sb = new StringBuilder("+").append(countryCode);
246	        for (int i = 0; i < national.length(); i += 3) {
247	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
248	        }
249	        return sb.toString();
250	    }
251	
252	    public String getEmail() {
253	        return this.email;
254	    }
255	
256	    /**
257	     * Set the owner's email address, normalizing it to lower case so it is both
258	     * stored and returned in a canonical form. A {@code null} value is left as-is.
259	     */
260	    public void setEmail(String email) {
261	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
262	    }
263	
264	    public String getTitle() {
265	        return this.title;
266	    }
267	
268	    public void setTitle(String title) {
269	        this.title = title;
270	    }
271	
272	    /**
273	     * Return the owner's salutation: the title and last name separated by a single
274	     * space (for example {@code 'DR who'}), or just the last name when no title was
275	     * supplied (a {@code null} or blank title).
276	     */
277	    public String getSalutation() {
278	        if (this.title == null || this.title.isBlank()) {
279	            return getLastName();
280	        }
281	        return this.title + " " + getLastName();
282	    }
283	
284	    public LocalDate getRegistrationDate() {
285	        return this.registrationDate;
286	    }
287	
288	    public void setRegistrationDate(LocalDate registrationDate) {
289	        this.registrationDate = registrationDate;
290	    }
291	
292	    public LocalDate getBirthDate() {
293	        return this.birthDate;
294	    }
295	
296	    public void setBirthDate(LocalDate birthDate) {
297	        this.birthDate = birthDate;
298	    }
299	
300	    /**
301	     * Return the owner's age band derived from the birth date, computed against the
302	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
303	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
304	     * either the birth date or the registration date is not set.
305	     */
306	    public String getAgeBand() {
307	        if (this.birthDate == null || this.registrationDate == null) {
308	            return null;
309	        }
310	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
311	        if (age < 18) {
312	            return "MINOR";
313	        }
314	        if (age < 65) {
315	            return "ADULT";
316	        }
317	        return "SENIOR";
318	    }
319	
320	    public String getPostcode() {
321	        return this.postcode;
322	    }
323	
324	    public void setPostcode(String postcode) {
325	        this.postcode = postcode;
326	    }
327	
328	    /**
329	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
330	     * is always valid (postcode is optional). When present, a postcode is valid if
331	     * the city has no known region, or if it is four digits falling within the
332	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
333	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
334	     */
335	    public boolean isPostcodeValidForCity() {
336	        if (this.postcode == null) {
337	            return true;
338	        }
339	        String region = CITY_REGION.get(this.city);
340	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
341	        if (range == null) {
342	            return true;
343	        }
344	        if (!this.postcode.matches("^[0-9]{4}$")) {
345	            return false;
346	        }
347	        int value = Integer.parseInt(this.postcode);
348	        return value >= range[0] && value <= range[1];
349	    }
350	
351	    public String getCustomerCode() {
352	        return this.customerCode;
353	    }
354	
355	    public void setCustomerCode(String customerCode) {
356	        this.customerCode = customerCode;
357	    }
358	
359	    /**
360	     * Return a single Luhn check digit (0-9) computed over the digits contained in
361	     * the owner's customer code, or {@code null} when the customer code is not set.
362	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
363	     * first, following the standard Luhn algorithm.
364	     */
365	    public Integer getCheckDigit() {
366	        if (this.customerCode == null) {
367	            return null;
368	        }
369	        int sum = 0;
370	        boolean doubleDigit = true;
371	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
372	            char c = this.customerCode.charAt(i);
373	            if (c < '0' || c > '9') {
374	                continue;
375	            }
376	            int digit = c - '0';
377	            if (doubleDigit) {
378	                digit *= 2;
379	                if (digit > 9) {
380	                    digit -= 9;
381	                }
382	            }
383	            sum += digit;
384	            doubleDigit = !doubleDigit;
385	        }
386	        return (10 - (sum % 10)) % 10;
387	    }
388	
389	    /**
390	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
391	     * where {@code YY} is the last two digits of the registration date's year (for
392	     * example {@code 'SMI-0007-M26'}). Returns {@code null} when either the customer
393	     * code or the registration date is not set.
394	     */
395	    public String getMembershipNumber() {
396	        if (this.customerCode == null || this.registrationDate == null) {
397	            return null;
398	        }
399	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
400	    }
401	
402	    public String getHouseholdId() {
403	        return this.householdId;
404	    }
405	
406	    public void setHouseholdId(String householdId) {
407	        this.householdId = householdId;
408	    }
409	
410	    public Integer getNamesakeCount() {
411	        return this.namesakeCount;
412	    }
413	
414	    /**
415	     * Return the owner's membership points, the raw score from which the
416	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
417	     * email address is present, {@code 1} when the owner has no namesakes
418	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
419	     * more, and {@code 3} when the owner's tenure (days since the registration
420	     * date) exceeds {@code 365}.
421	     */
422	    public Integer getMembershipPoints() {
423	        int points = 0;
424	        boolean hasEmail = this.email != null && !this.email.isBlank();
425	        if (hasEmail) {
426	            points += 2;
427	        }
428	        if (this.namesakeCount != null && this.namesakeCount == 0) {
429	            points += 1;
430	        }
431	        if (this.householdSize != null && this.householdSize >= 3) {
432	            points += 2;
433	        }
434	        if (this.registrationDate != null
435	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
436	            points += 3;
437	        }
438	        return points;
439	    }
440	
441	    /**
442	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
443	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
444	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
445	     * {@code 4} for {@code 6} or more.
446	     */
447	    public Integer getMembershipLevel() {
448	        int points = getMembershipPoints();
449	        if (points >= 6) {
450	            return 4;
451	        }
452	        if (points >= 4) {
453	            return 3;
454	        }
455	        if (points >= 2) {
456	            return 2;
457	        }
458	        return 1;
459	    }
460	
461	    public void setNamesakeCount(Integer namesakeCount) {
462	        this.namesakeCount = namesakeCount;
463	    }
464	
465	    public Integer getHouseholdSize() {
466	        return this.householdSize;
467	    }
468	
469	    public void setHouseholdSize(Integer householdSize) {
470	        this.householdSize = householdSize;
471	    }
472	
473	    /**
474	     * Whether this owner, when created, softly matched an existing owner by
475	     * sharing the same last name and postcode but with a different telephone.
476	     * Such an owner is still created; the flag surfaces the likely duplication.
477	     */
478	    public Boolean getPossibleDuplicate() {
479	        return this.possibleDuplicate;
480	    }
481	
482	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
483	        this.possibleDuplicate = possibleDuplicate;
484	    }
485	
486	    /**
487	     * The id of the existing owner this owner softly matched on last name and
488	     * postcode (with a different telephone), or {@code null} when there is no
489	     * such match.
490	     */
491	    public Integer getPossibleDuplicateOf() {
492	        return this.possibleDuplicateOf;
493	    }
494	
495	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
496	        this.possibleDuplicateOf = possibleDuplicateOf;
497	    }
498	
499	    /**
500	     * Whether this owner has been soft-deleted. A newly created owner is not
501	     * deleted; {@code DELETE /api/owners/{id}} sets this flag rather than removing
502	     * the row, and a flagged owner is ignored by the create endpoint's duplicate
503	     * and identity checks.
504	     */
505	    public boolean isDeleted() {
506	        return this.deleted;
507	    }
508	
509	    public void setDeleted(boolean deleted) {
510	        this.deleted = deleted;
511	    }
512	
513	    /**
514	     * Whether more than 80 owners had already been registered on this owner's
515	     * registration day at the time it was created, flagging a bulk-signup surge.
516	     */
517	    public Boolean getBulkSignupWarning() {
518	        return this.bulkSignupWarning;
519	    }
520	
521	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
522	        this.bulkSignupWarning = bulkSignupWarning;
523	    }
524	
525	    /**
526	     * Return the owner's locality (region), preferring the postcode: when the
527	     * postcode is present and falls within a known region's inclusive range
528	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
529	     * region is returned. Otherwise the value falls back to the fixed
530	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
531	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
532	     * table. This yields the same region for known cities but disambiguates
533	     * cities that share a name.
534	     */
535	    public String getLocality() {
536	        String regionFromPostcode = regionForPostcode();
537	        if (regionFromPostcode != null) {
538	            return regionFromPostcode;
539	        }
540	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
541	    }
542	
543	    /**
544	     * Return the owner's IANA timezone, derived from the locality/region via the
545	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
546	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
547	     * {@code null} when the region is not in the table.
548	     */
549	    public String getTimezone() {
550	        return REGION_TIMEZONE.get(getLocality());
551	    }
552	
553	    /**
554	     * Look up the region whose inclusive postcode range contains this owner's
555	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
556	     * known range.
557	     */
558	    private String regionForPostcode() {
559	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
560	            return null;
561	        }
562	        int value = Integer.parseInt(this.postcode);
563	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
564	            int[] range = entry.getValue();
565	            if (value >= range[0] && value <= range[1]) {
566	                return entry.getKey();
567	            }
568	        }
569	        return null;
570	    }
571	
572	    /**
573	     * Return the owner's preferred contact channel, derived from the stored
574	     * contact details: {@code 'EMAIL'} when an email address is present,
575	     * otherwise {@code 'PHONE'}.
576	     */
577	    public String getContactPreference() {
578	        boolean hasEmail = this.email != null && !this.email.isBlank();
579	        return hasEmail ? "EMAIL" : "PHONE";
580	    }
581	
582	    /**
583	     * Return the owner's derived identity key, which consolidates all duplicate
584	     * detection into a single value formed as
585	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
586	     * The telephone and email are already stored in their normalized (E.164 /
587	     * lower-cased) forms; a missing email or household id contributes an empty
588	     * segment. A create is rejected only when a new owner's whole identity key
589	     * equals an existing owner's.
590	     */
591	    public String getIdentityKey() {
592	        String telephonePart = this.telephone == null ? "" : this.telephone;
593	        String emailPart = (this.email == null) ? "" : this.email;
594	        String householdPart = (this.householdId == null) ? "" : this.householdId;
595	        return telephonePart + "|" + emailPart + "|" + householdPart;
596	    }
597	
598	    protected Set<Pet> getPetsInternal() {
599	        if (this.pets == null) {
600	            this.pets = new HashSet<>();
601	        }
602	        return this.pets;
603	    }
604	
605	    protected void setPetsInternal(Set<Pet> pets) {
606	        this.pets = pets;
607	    }
608	
609	    public List<Pet> getPets() {
610	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
611	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
612	        return Collections.unmodifiableList(sortedPets);
613	    }
614	
615	    public void setPets(List<Pet> pets) {
616	        this.pets = new HashSet<>(pets);
617	    }
618	
619	    public void addPet(Pet pet) {
620	        getPetsInternal().add(pet);
621	        pet.setOwner(this);
622	    }
623	
624	    /**
625	     * Return the Pet with the given name, or null if none found for this Owner.
626	     *
627	     * @param name to test
628	     * @return true if pet name is already in use
629	     */
630	    public Pet getPet(String name) {
631	        return getPet(name, false);
632	    }
633	
634	    /**
635	     * Return the Pet with the given name, or null if none found for this Owner.
636	     *
637	     * @param name to test
638	     * @return true if pet name is already in use
639	     */
640	    public Pet getPet(String name, boolean ignoreNew) {
641	        name = name.toLowerCase();
642	        for (Pet pet : getPetsInternal()) {
643	            if (!ignoreNew || !pet.isNew()) {
644	                String compName = pet.getName();
645	                compName = compName.toLowerCase();
646	                if (compName.equals(name)) {
647	                    return pet;
648	                }
649	            }
650	        }
651	        return null;
652	    }
653	
654	    public Pet getPet(Integer petId) {
655	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
656	    }
657	
658	    @Override
659	    public String toString() {
660	        return new ToStringCreator(this)
661	
662	            .append("id", this.getId())
663	            .append("new", this.isNew())
664	            .append("lastName", this.getLastName())
665	            .append("firstName", this.getFirstName())
666	            .append("address", this.address)
667	            .append("city", this.city)
668	            .append("telephone", this.telephone)
669	            .append("email", this.email)
670	            .toString();
671	    }
672	}
